import pytest
from candidate import is_simple_power

class TestIsSimplePower(unittest.TestCase):
    def test_simple_power_one_to_any_number_is_true(self):
        self.assertTrue(is_simple_power(1, 4))

    def test_simple_power_two_base_two(self):
        self.assertTrue(is_simple_power(2, 2))

    def test_simple_power_eight_base_two(self):
        self.assertTrue(is_simple_power(8, 2))

    def test_simple_power_three_base_two_is_false(self):
        self.assertFalse(is_simple_power(3, 2))

    def test_simple_power_three_base_one_is_false(self):
        self.assertFalse(is_simple_power(3, 1))

    def test_simple_power_five_base_three_is_false(self):
        self.assertFalse(is_simple_power(5, 3))

    def test_simple_power_one_base_one_is_true(self):
        self.assertTrue(is_simple_power(1, 1))

    def test_simple_power_one_base_two_is_true(self):
        self.assertTrue(is_simple_power(1, 2))

    def test_simple_power_one_base_ten_is_true(self):
        self.assertTrue(is_simple_power(1, 10))

    def test_simple_power_nine_base_three(self):
        self.assertTrue(is_simple_power(9, 3))

    def test_simple_power_twenty_seven_base_three(self):
        self.assertTrue(is_simple_power(27, 3))

    def test_simple_power_sixteen_base_two(self):
        self.assertTrue(is_simple_power(16, 2))

    def test_simple_power_hundred_base_ten(self):
        self.assertTrue(is_simple_power(100, 10))

    def test_simple_power_thousand_base_ten(self):
        self.assertTrue(is_simple_power(1000, 10))

    def test_simple_power_thirty_two_base_two(self):
        self.assertTrue(is_simple_power(32, 2))

    def test_simple_power_thirty_three_base_two_is_false(self):
        self.assertFalse(is_simple_power(33, 2))

    def test_simple_power_ten_base_two_is_false(self):
        self.assertFalse(is_simple_power(10, 2))

    def test_simple_power_one_hundred_twenty_five_base_five(self):
        self.assertTrue(is_simple_power(125, 5))

    def test_simple_power_one_hundred_six_base_five_is_false(self):
        self.assertFalse(is_simple_power(126, 5))

    def test_simple_power_base_one_x_two_is_false(self):
        self.assertFalse(is_simple_power(2, 1))

    def test_simple_power_base_one_x_hundred_is_false(self):
        self.assertFalse(is_simple_power(100, 1))

    def test_simple_power_base_one_x_zero_is_false(self):
        self.assertFalse(is_simple_power(0, 1))

    def test_simple_power_base_four_x_four(self):
        self.assertTrue(is_simple_power(4, 4))

    def test_simple_power_base_four_x_sixteen(self):
        self.assertTrue(is_simple_power(16, 4))

    def test_simple_power_base_four_x_sixteen_correct(self):
        self.assertTrue(is_simple_power(16, 4))

    def test_simple_power_base_four_x_fifteen_is_false(self):
        self.assertFalse(is_simple_power(15, 4))

    def test_simple_power_base_zero_x_one_is_true(self):
        self.assertTrue(is_simple_power(1, 0))

    def test_simple_power_base_zero_x_zero_is_false(self):
        self.assertFalse(is_simple_power(0, 0))

    def test_simple_power_negative_base_negative_one(self):
        self.assertTrue(is_simple_power(1, -1))

    def test_simple_power_negative_base_two_positive_x(self):
        self.assertFalse(is_simple_power(2, -2))

    def test_simple_power_negative_base_four_positive_x(self):
        self.assertTrue(is_simple_power(4, -2))

    def test_simple_power_negative_base_eight_positive_x(self):
        self.assertFalse(is_simple_power(8, -2))

    def test_simple_power_large_power_of_two(self):
        self.assertTrue(is_simple_power(1024, 2))

    def test_simple_power_large_not_power_of_two(self):
        self.assertFalse(is_simple_power(1025, 2))

    def test_simple_power_base_seven_x_four_nine(self):
        self.assertTrue(is_simple_power(49, 7))

    def test_simple_power_base_seven_x_fifty_is_false(self):
        self.assertFalse(is_simple_power(50, 7))

    def test_simple_power_base_eleven_x_one_hundred_twenty_one(self):
        self.assertTrue(is_simple_power(121, 11))

    def test_simple_power_base_eleven_x_one_hundred_twenty_is_false(self):
        self.assertFalse(is_simple_power(120, 11))


if __name__ == '__main__':
    unittest.main()
